import test from 'node:test';import assert from 'node:assert/strict';import {create,move,preview,advance,runPolicy,configure} from './engine.js';
test('a valuable accommodation earns its benefit and charges setup once',()=>{let s=move(create(),'export','tailored');assert.equal(preview(s).net,17);s=advance(s);assert.equal(preview(s).changeCost,0);assert.equal(preview(s).revenue,14);assert.equal(preview(s).maintenance,5.7);});
test('retirement charges exit cost and stops future upkeep',()=>{let s=advance(move(create(),'invoice','tailored'));s=move(s,'invoice','retired');assert.equal(preview(s).retirement,5);assert.equal(preview(s).maintenance,0);s=advance(s);assert.equal(preview(s).retirement,0);assert.throws(()=>move(s,'invoice','tailored'),/retirement/);});
test('shared surfaces create pair cost and a standard reduces friction and reuse setup',()=>{let s=advance(move(create(),'export','standard'));s=move(s,'audit','tailored');const p=preview(s);assert.equal(p.reuse,6);assert.equal(p.changeCost,4);assert.equal(p.pairs.length,1);assert.equal(p.pairs[0].cost,1);});
test('policies replay exactly, total equals settled net, and parameter tradeoffs can reverse rankings',()=>{for(const kind of ['tailor','reuse']){const a=runPolicy(kind);assert.deepEqual(a,runPolicy(kind));assert.ok(Math.abs(a.value-a.history.reduce((s,h)=>s+h.net,0))<1e-9);}const low={aging:0,pairCost:0},high={aging:3,pairCost:6};assert.ok(runPolicy('tailor',low).value>runPolicy('reuse',low).value);assert.ok(runPolicy('reuse',high).value>runPolicy('tailor',high).value);assert.throws(()=>configure(create(),{aging:-1}));});
